/**
 * The one mapping between the Studio's message model and assistant-ui's.
 *
 * Kept in one place and pure, so the thread can be tested without a runtime and
 * the runtime can be swapped without touching the transcript. Anything the
 * conversion does not understand is dropped rather than rendered as raw JSON:
 * an unknown part must never reach the screen as machine text.
 */

import type { ThreadMessage, ThreadMessageLike } from "@assistant-ui/react";

import type { ChatAttachment, ChatMessage, ChatPart, StudioError } from "../types";
import type { UiNode } from "../ui/protocol";

/** The name our generated-surface parts travel under. */
export const SURFACE_PART = "odi-surface";

type LikePart = Exclude<ThreadMessageLike["content"], string>[number];

const TOOL_RESULT: Record<string, Record<string, unknown>> = {
  ok: { status: "ok" },
  error: { status: "error", isError: true },
  declined: { status: "declined" },
};

function toPart(part: ChatPart): LikePart | null {
  switch (part.kind) {
    case "text":
      return { type: "text", text: part.text };

    case "reasoning":
      return { type: "reasoning", text: part.text };

    case "ui":
      return { type: `data-${SURFACE_PART}` as const, id: part.id, data: part.node };

    case "source":
      return {
        type: "source",
        sourceType: "document",
        id: part.id,
        title: part.title,
        mediaType: part.mediaType,
        ...(part.filename ? { filename: part.filename } : {}),
      };

    case "tool": {
      const approval = part.approval;
      if (approval) {
        // A pending write is a question, not a result: the runtime keeps the
        // message in `requires-action` until the user answers.
        return {
          type: "tool-call",
          toolCallId: part.id,
          toolName: part.name,
          args: {},
          argsText: "{}",
          approval: { id: approval.id, prompt: approval.prompt },
        };
      }
      return {
        type: "tool-call",
        toolCallId: part.id,
        toolName: part.name,
        args: {},
        argsText: "{}",
        result: { ...(TOOL_RESULT[part.status] ?? {}), preview: part.preview ?? "" },
        isError: part.status === "error",
      };
    }

    default:
      return null;
  }
}

function attachmentParts(attachments: ChatAttachment[]) {
  return attachments.map((attachment) => ({
    id: attachment.id,
    type: attachment.contentType.startsWith("image/") ? ("image" as const) : ("document" as const),
    name: attachment.name,
    contentType: attachment.contentType,
    status: { type: "complete" as const },
    content: [
      {
        type: "file" as const,
        data: attachment.id,
        mimeType: attachment.contentType,
        filename: attachment.name,
      },
    ],
  }));
}

/**
 * A Studio turn as the runtime renders it.
 *
 * `content` stays the concatenated prose so history replays byte-identically;
 * `parts` is what the thread shows.
 */
export function toThreadMessageLike(message: ChatMessage): ThreadMessageLike {
  if (message.role === "notice") {
    return {
      id: message.id,
      role: "system",
      content: [{ type: "text", text: message.content }],
    };
  }

  const parts = (message.parts ?? []).flatMap((part) => {
    const converted = toPart(part);
    return converted ? [converted] : [];
  });

  const content: readonly LikePart[] =
    parts.length > 0
      ? parts
      : message.content
        ? [{ type: "text", text: message.content }]
        : [];

  const failed = message.error !== undefined;

  return {
    id: message.id,
    role: message.role,
    content,
    ...(message.role === "user" && message.attachments?.length
      ? { attachments: attachmentParts(message.attachments) }
      : {}),
    ...(failed
      ? {
          status: {
            type: "incomplete" as const,
            reason: "error" as const,
            error: message.error as never,
          },
        }
      : {}),
    ...(failed || message.retryText
      ? {
          metadata: {
            custom: {
              ...(message.error ? { error: message.error } : {}),
              ...(message.retryText ? { retryText: message.retryText } : {}),
            },
          },
        }
      : {}),
  };
}

function readCustom(message: ThreadMessage): Record<string, unknown> {
  return (message.metadata?.custom ?? {}) as Record<string, unknown>;
}

/**
 * The inverse: a runtime message back in the Studio's own model.
 *
 * The runtime hands a branch switch back as the originals it was given, so this
 * is only needed when a message arrives from somewhere else — an import, or a
 * future remote thread.
 */
export function toChatMessage(
  message: ThreadMessage,
  parentId: string | null = null,
): ChatMessage {
  const text = message.content
    .filter((part) => part.type === "text")
    .map((part) => (part as unknown as { text: string }).text)
    .join("");

  const custom = readCustom(message);
  const parts: ChatPart[] = [];

  for (const part of message.content) {
    switch (part.type) {
      case "text":
        parts.push({ kind: "text", text: part.text });
        break;

      case "reasoning":
        parts.push({ kind: "reasoning", text: part.text });
        break;

      case "source":
        parts.push({
          kind: "source",
          id: part.id,
          title: part.sourceType === "url" ? (part.title ?? part.url) : part.title,
          mediaType: part.sourceType === "document" ? part.mediaType : "text/html",
          ...(part.sourceType === "document" && part.filename
            ? { filename: part.filename }
            : {}),
        });
        break;

      case "tool-call": {
        const result = part.result as { status?: string; preview?: string } | undefined;
        const approval = part.approval;
        const awaiting = approval !== undefined && approval.approved === undefined && !part.result;
        parts.push({
          kind: "tool",
          id: part.toolCallId,
          name: part.toolName,
          status: awaiting
            ? "running"
            : part.isError
              ? "error"
              : result?.status === "declined"
                ? "declined"
                : "ok",
          ...(result?.preview ? { preview: result.preview } : {}),
          ...(awaiting ? { approval: { id: approval.id, prompt: approval.prompt ?? "" } } : {}),
        });
        break;
      }

      case "data":
        if (part.name === SURFACE_PART) {
          parts.push({
            kind: "ui",
            id: part.id ?? `ui-${parts.length}`,
            node: part.data as UiNode,
          });
        }
        break;

      default:
        break;
    }
  }

  const attachments: ChatAttachment[] | undefined = message.attachments?.length
    ? message.attachments.map((attachment) => ({
        id: attachment.id,
        name: attachment.name,
        contentType: attachment.contentType ?? "application/octet-stream",
        size: 0,
      }))
    : undefined;

  const role = message.role === "system" ? "notice" : message.role;

  return {
    id: message.id,
    parentId,
    role,
    content: text,
    ...(parts.length ? { parts } : {}),
    ...(attachments ? { attachments } : {}),
    ...(custom.error ? { error: custom.error as StudioError } : {}),
    ...(custom.retryText ? { retryText: String(custom.retryText) } : {}),
  };
}

/** The readable text of one appended message, for the Studio's send path. */
export function textOf(message: { content: string | readonly { type: string }[] }): string {
  if (typeof message.content === "string") {
    return message.content.trim();
  }
  return message.content
    .filter((part) => part.type === "text")
    .map((part) => (part as unknown as { text: string }).text)
    .join("\n")
    .trim();
}

import { describe, expect, it } from "vitest";

import type { ChatMessage } from "../types";
import { catalogManifest } from "../ui/catalog";
import { parseUiSpec, type UiNode } from "../ui/protocol";
import { SURFACE_PART, textOf, toThreadMessageLike } from "./convert";

function nodeOf(spec: unknown): UiNode {
  const parsed = parseUiSpec(spec, catalogManifest());
  if (!parsed.ok) {
    throw new Error(parsed.reason);
  }
  return parsed.node;
}

const card = nodeOf({
  type: "outcome-card",
  props: {
    id: "O-1",
    statement: "Minimize the time it takes to propagate secrets",
    importance: 9,
    satisfaction: 3,
  },
});

function assistant(overrides: Partial<ChatMessage> = {}): ChatMessage {
  return {
    id: "m-1",
    parentId: null,
    role: "assistant",
    content: "",
    ...overrides,
  };
}

describe("toThreadMessageLike", () => {
  it("maps prose to a text part", () => {
    const message = toThreadMessageLike(assistant({ content: "Hello." }));

    expect(message.role).toBe("assistant");
    expect(message.content).toEqual([{ type: "text", text: "Hello." }]);
  });

  it("keeps the agent's part order", () => {
    const message = toThreadMessageLike(
      assistant({
        content: "beforeafter",
        parts: [
          { kind: "text", text: "before" },
          { kind: "ui", id: "ui-1", node: card },
          { kind: "text", text: "after" },
        ],
      }),
    );

    expect((message.content as unknown as { type: string }[]).map((part) => part.type)).toEqual([
      "text",
      `data-${SURFACE_PART}`,
      "text",
    ]);
  });

  it("carries a generated surface as a named data part", () => {
    const message = toThreadMessageLike(
      assistant({
        parts: [{ kind: "ui", id: "ui-1", node: card }],
      }),
    );

    const part = (message.content as { type: string; id?: string; data?: UiNode }[])[0];
    expect(part.type).toBe(`data-${SURFACE_PART}`);
    expect(part.id).toBe("ui-1");
    expect(part.data).toEqual(card);
  });

  it("maps reasoning to a reasoning part", () => {
    const message = toThreadMessageLike(
      assistant({ parts: [{ kind: "reasoning", text: "weighing options" }] }),
    );

    expect(message.content).toEqual([{ type: "reasoning", text: "weighing options" }]);
  });

  it("maps a finished tool call to a result, not a question", () => {
    const message = toThreadMessageLike(
      assistant({
        parts: [
          { kind: "tool", id: "call-1", name: "get_jobs", status: "ok", preview: "3 jobs" },
        ],
      }),
    );

    const part = (
      message.content as {
        type: string;
        toolCallId?: string;
        toolName?: string;
        result?: { status?: string; preview?: string };
        isError?: boolean;
      }[]
    )[0];
    expect(part.type).toBe("tool-call");
    expect(part.toolCallId).toBe("call-1");
    expect(part.toolName).toBe("get_jobs");
    expect(part.result).toEqual({ status: "ok", preview: "3 jobs" });
    expect(part.isError).toBe(false);
  });

  it("marks a failed tool call as an error without inventing a result", () => {
    const message = toThreadMessageLike(
      assistant({
        parts: [{ kind: "tool", id: "call-1", name: "get_jobs", status: "error" }],
      }),
    );

    const part = (
      message.content as unknown as { isError?: boolean; result?: { status?: string } }[]
    )[0];
    expect(part.isError).toBe(true);
    expect(part.result?.status).toBe("error");
  });

  it("turns a pending approval into a question the runtime keeps open", () => {
    const message = toThreadMessageLike(
      assistant({
        parts: [
          {
            kind: "tool",
            id: "call-1",
            name: "add_job",
            status: "running",
            approval: { id: "apv_1", prompt: "Allow the assistant to add job?" },
          },
        ],
      }),
    );

    const part = (
      message.content as unknown as {
        approval?: { id?: string; prompt?: string };
        result?: unknown;
      }[]
    )[0];
    expect(part.approval).toEqual({ id: "apv_1", prompt: "Allow the assistant to add job?" });
    expect(part.result).toBeUndefined();
  });

  it("maps a source to a document citation", () => {
    const message = toThreadMessageLike(
      assistant({
        parts: [
          {
            kind: "source",
            id: "src-1",
            title: "get_jobs — JOB-1",
            filename: "get_jobs",
            mediaType: "application/json",
          },
        ],
      }),
    );

    expect(message.content).toEqual([
      {
        type: "source",
        sourceType: "document",
        id: "src-1",
        title: "get_jobs — JOB-1",
        mediaType: "application/json",
        filename: "get_jobs",
      },
    ]);
  });

  it("drops a part kind it does not know rather than rendering raw JSON", () => {
    const message = toThreadMessageLike(
      assistant({
        content: "still here",
        parts: [{ kind: "mystery" } as never],
      }),
    );

    expect(message.content).toEqual([{ type: "text", text: "still here" }]);
  });

  it("renders a notice as a system turn", () => {
    const message = toThreadMessageLike({
      id: "n-1",
      parentId: null,
      role: "notice",
      content: "**Studio status**",
    });

    expect(message.role).toBe("system");
  });

  it("carries the failure and the retry text so the transcript can offer both", () => {
    const error = {
      code: "mcp_unreachable",
      message: "The MCP server is unreachable.",
      retryable: true,
    };
    const message = toThreadMessageLike(
      assistant({ error, retryText: "list the jobs" }),
    );

    expect(message.status).toMatchObject({ type: "incomplete", reason: "error" });
    expect(message.metadata?.custom).toEqual({ error, retryText: "list the jobs" });
  });

  it("carries attachments on a user turn only", () => {
    const message = toThreadMessageLike({
      id: "m-1",
      parentId: null,
      role: "user",
      content: "look at this",
      attachments: [
        { id: "a-1", name: "notes.md", contentType: "text/markdown", size: 12 },
      ],
    });

    expect(message.attachments?.[0]).toMatchObject({
      id: "a-1",
      name: "notes.md",
      status: { type: "complete" },
    });
  });
});

describe("textOf", () => {
  it("reads the text parts of an appended message", () => {
    expect(
      textOf({
        content: [
          { type: "text", text: "first" },
          { type: "file", data: "x" },
          { type: "text", text: "second" },
        ] as never,
      }),
    ).toBe("first\nsecond");
  });

  it("passes a plain string through, trimmed", () => {
    expect(textOf({ content: "  hi  " })).toBe("hi");
  });
});
